let summitGroupsOpen=safeParse(storageGet(SUMMIT_GROUP_KEY),{planned:true,completed:false,remaining:false});
function saveSummitGroups(){storageSet(SUMMIT_GROUP_KEY,JSON.stringify(summitGroupsOpen))}

function summitCardHtml(peak){
 const first=firstAscentDate(peak),ascentCount=peak.ascents?.length||0;
 return `<button class="summit-card status-${peak.status}" type="button" data-summit-name="${escapeHtml(peak.name)}" aria-label="Open details for ${escapeHtml(summitDisplayName(peak))}">
   <div class="summit-card-top">
    <span class="summit-status">${SUMMIT_STATUS_LABELS[peak.status]}</span>
    <span class="summit-rank">${peak.ranked?'Ranked':'Named · unranked'}</span>
   </div>
   <h3>${summitDisplayName(peak)}</h3>
   <p>${peak.range}${peak.difficulty?` · ${peak.difficulty}`:''}${peak.elevation?` · ${Number(peak.elevation).toLocaleString()}'`:''}</p>
   ${peak.status==='completed'
     ?`<div class="summit-card-facts"><b>${first?formatClimbDate(first):'Date not yet entered'}</b><span>${ascentCount?`${ascentCount} recorded ascent${ascentCount===1?'':'s'}`:'Completion confirmed'}</span></div>`
     :peak.status==='planned'
       ?'<small>Lake Como objective; not counted until summited.</small>'
       :'<small>Future Colorado objective.</small>'}
   <span class="summit-open">View details →</span>
  </button>`;
}

function renderSummitLedger(){
 const grid=document.getElementById('summitGrid');
 if(!grid)return;
 const {query,range}=currentSummitFilters();
 const filtered=COLORADO_SUMMITS.filter(peak=>{
  const text=summitSearchText(peak);
  return (!query||text.includes(query))&&(range==='all'||peak.range===range)
 });
 if(!filtered.length){
  grid.innerHTML='<div class="empty-state">No summits match these filters.</div>';
  return;
 }
 /* A search that hides its own matches inside a collapsed group looks broken. Force groups open while searching. */
 const forceOpen=!!query;
 grid.innerHTML=SUMMIT_GROUP_ORDER.map(group=>{
  const rows=filtered.filter(p=>p.status===group.id).sort((a,b)=>summitSearchRank(a,query)-summitSearchRank(b,query)||a.name.localeCompare(b.name));
  if(!rows.length)return '';
  const open=forceOpen||!!summitGroupsOpen[group.id];
  return `<section class="summit-group" data-group="${group.id}">
   <button class="summit-group-head" type="button" data-group-toggle="${group.id}" aria-expanded="${open}" aria-controls="summitGroupBody-${group.id}">
    <span class="summit-group-label"><b>${escapeHtml(group.title)}</b><small>${escapeHtml(group.note)}</small></span>
    <span class="summit-group-meta"><span class="summit-group-count">${rows.length}</span><span class="summit-group-action">${open?'Collapse':'Open'}</span><span class="summit-group-chevron" aria-hidden="true">${open?'▾':'▸'}</span></span>
   </button>
   <div class="summit-group-body" id="summitGroupBody-${group.id}"${open?'':' hidden'}>
    <div class="summit-grid-inner">${rows.map(summitCardHtml).join('')}</div>
   </div>
  </section>`;
 }).join('');
}
function announceSummitGroups(msg){
 const el=document.getElementById('summitGroupStatus');
 if(el)el.textContent=msg;
}
function groupTitle(id){return SUMMIT_GROUP_ORDER.find(g=>g.id===id)?.title||id}
function toggleSummitGroup(id){
 summitGroupsOpen[id]=!summitGroupsOpen[id];
 saveSummitGroups();
 renderSummitLedger();
 const n=COLORADO_SUMMITS.filter(p=>p.status===id).length;
 announceSummitGroups(`${groupTitle(id)} ${summitGroupsOpen[id]?'expanded':'collapsed'}, ${n} summits.`);
}
function setAllSummitGroups(open){
 SUMMIT_GROUP_ORDER.forEach(g=>{summitGroupsOpen[g.id]=open});
 saveSummitGroups();
 renderSummitLedger();
 announceSummitGroups(open?'All summit groups expanded.':'All summit groups collapsed.');
}

function openSummitDetail(name){
 const peak=COLORADO_SUMMITS.find(item=>item.name===name);if(!peak)return;
 const overlay=document.getElementById('summitDetailOverlay');
 document.getElementById('summitDetailTitle').textContent=summitDisplayName(peak);
 document.getElementById('summitDetailSubtitle').textContent=`${peak.range}${peak.elevation?` · ${Number(peak.elevation).toLocaleString()} feet`:''}`;
 const history=peak.ascents?.length
  ?`<section class="summit-detail-section"><div class="kicker">Recorded climb history</div>
    <div class="ascent-list">${peak.ascents.map((ascent,index)=>`
      <article class="ascent-row">
       <div><strong>${escapeHtml(formatClimbDate(ascent.date))}</strong><span>${escapeHtml(ascent.solo?'Solo':ascent.partners||'Partners not recorded')}</span></div>
       ${ascent.milestone?`<div class="outing-badge milestone-badge"><b>Milestone</b><span>${escapeHtml(ascent.milestone)}</span></div>`:''}
       ${ascent.outingName?`<div class="outing-badge"><b>${escapeHtml(ascent.outingClass)}</b><span>${escapeHtml(ascent.outingName)}</span></div>`:''}
       ${ascent.memory?`<p><b>Memory:</b> ${escapeHtml(ascent.memory)}</p>`:''}
       ${ascent.conditions?`<p><b>Conditions:</b> ${escapeHtml(ascent.conditions)}</p>`:''}
       ${ascent.gear?`<p><b>Gear noted:</b> ${escapeHtml(ascent.gear)}</p>`:''}
       ${ascent.note?`<p>${escapeHtml(ascent.note)}</p>`:''}
      </article>`).join('')}</div></section>`
  :peak.status==='completed'
    ?'<section class="summit-detail-section"><div class="kicker">Recorded climb history</div><p>Completion is confirmed by the Aug. 1, 2026 checklist, but the date and partners have not yet been entered.</p></section>'
    :'';
 /* v8.3 — unclimbed peaks previously showed nothing here. Fall back to the
    curated Route Intelligence profile, which covers every remaining peak. */
 const profile=peak.route?null:riStandardProfileFor(peak.name);
 const profileHtml=profile?riProfileDetailHtml(profile):'';
 const route=peak.route
  ?`<section class="summit-detail-section route-reference">
      <div class="kicker">Current 14ers.com standard-route reference</div>
      <div class="route-facts">
       <span><b>${peak.route}</b>Route</span>
       <span><b>${peak.difficulty}</b>Difficulty</span>
       <span><b>${peak.miles} mi</b>Round trip</span>
       <span><b>${Number(peak.gain).toLocaleString()}'</b>Elevation gain</span>
      </div>
      ${peak.note?`<p class="route-note">${peak.note}</p>`:''}
      <p class="route-disclaimer">These are current standard-route reference values, not a reconstruction of Don’s historical GPS track or exact starting point.</p>
      <a class="route-link" href="${peak.url}" target="_blank" rel="noopener">Open official 14ers.com route guide ↗</a>
    </section>`
  :'';
 document.getElementById('summitDetailBody').innerHTML=history+route+profileHtml;
 overlay.hidden=false;document.body.style.overflow='hidden';
 document.getElementById('summitDetailClose').focus()
}
function closeSummitDetail(){
 const overlay=document.getElementById('summitDetailOverlay');
 const title=document.getElementById('summitDetailTitle').textContent;
 overlay.hidden=true;document.body.style.overflow='';
 [...document.querySelectorAll('[data-summit-name]')].find(button=>summitDisplayName({name:button.dataset.summitName})===title)?.focus()
}

// ---------------------------------------------------------------------------
// SINGLE SOURCE OF TRUTH
// Every summit statistic and milestone shown anywhere in the app is derived
// here from COLORADO_SUMMITS. Nothing is hardcoded in index.html. If the
// ledger changes, every displayed number changes with it — the dashboard,
// the ledger stat row, and the milestone strip cannot disagree.
// ---------------------------------------------------------------------------
const PERSONAL_GOAL=50;
function ledgerFacts(){
 const completedPeaks=COLORADO_SUMMITS.filter(p=>p.status==='completed');
 const planned=COLORADO_SUMMITS.filter(p=>p.status==='planned').length;
 const ascents=[];
 completedPeaks.forEach(p=>(p.ascents||[]).forEach(a=>ascents.push({peak:p,ascent:a})));
 ascents.sort((a,b)=>String(a.ascent.date).localeCompare(String(b.ascent.date)));
 const dated=ascents.filter(x=>x.ascent.date);
 return {
  completed:completedPeaks.length,
  planned,
  projected:completedPeaks.length+planned,
  ranked:completedPeaks.filter(p=>p.ranked).length,
  ascentCount:ascents.length,
  solo:ascents.filter(x=>x.ascent.solo).length,
  total:COLORADO_SUMMITS.length,
  totalNamed:COLORADO_SUMMITS.length,
  remaining:COLORADO_SUMMITS.length-completedPeaks.length-planned,
  goal:PERSONAL_GOAL,
  firstAscent:dated[0]||null,
  milestones:dated.filter(x=>x.ascent.milestone)
 };
}
function shortClimbDate(iso){
 if(!iso)return '';
 const [y,m,d]=String(iso).split('-').map(Number);
 const months=['Jan.','Feb.','Mar.','Apr.','May','June','July','Aug.','Sept.','Oct.','Nov.','Dec.'];
 return `${months[m-1]} ${d}, ${y}`;
}
function renderLedgerFacts(){
 const f=ledgerFacts();
 const recordDescription=document.getElementById('summitRecordDescription');
 if(recordDescription)recordDescription.textContent=`Search all ${f.totalNamed} named summits: ${f.completed} completed, ${f.planned} planned, and ${f.remaining} remaining.`;
 const set=(id,val)=>{const el=document.getElementById(id);if(el)el.textContent=val};
 set('ledgerCompletedCount',f.completed);
 set('ledgerProjectedCount',f.projected);
 set('statRanked',f.ranked);
 set('statAscents',f.ascentCount);
 set('statSolo',f.solo);
 set('statGoal',`${f.goal}+`);
 set('goalSummary',`${f.projected} / ${f.goal}`);
 set('heroCompleted',f.completed);
 set('heroPlanned',f.planned);
 set('heroGoal',`${f.goal}+`);
 const meter=document.getElementById('ledgerMeterFill');
 if(meter)meter.style.width=`${Math.min(100,f.completed/f.total*100)}%`;
 const goalBar=document.getElementById('goalBar');
 if(goalBar)goalBar.style.width=`${Math.min(100,Math.round(f.projected/f.goal*100))}%`;
 // Milestone strip is built from the same ascent records the summit pages use.
 const strip=document.getElementById('milestoneStrip');
 if(strip){
  const cards=[];
  if(f.firstAscent)cards.push({label:'First climb',value:`${f.firstAscent.peak.name} · ${shortClimbDate(f.firstAscent.ascent.date)}`});
  f.milestones.forEach(x=>{
   if(f.firstAscent&&x===f.firstAscent)return;
   cards.push({label:x.ascent.milestone.replace(/\s*[—-].*$/,'').replace(/\.$/,'').trim()||'Milestone',value:`${x.peak.name} · ${shortClimbDate(x.ascent.date)}`});
  });
  strip.innerHTML=cards.slice(0,4).map(c=>`<span><b>${escapeHtml(c.label)}</b>${escapeHtml(c.value)}</span>`).join('');
 }
}
function setupSummitLedger(){
 const grid=document.getElementById('summitGrid');if(!grid)return;
 renderLedgerFacts();

 const rangeSelect=document.getElementById('summitRangeFilter');
 if(rangeSelect)[...new Set(COLORADO_SUMMITS.map(p=>p.range))].forEach(range=>{
  const option=document.createElement('option');option.value=range;option.textContent=range;rangeSelect.append(option)
 });
 ['summitSearch','summitRangeFilter'].forEach(id=>{
  document.getElementById(id)?.addEventListener(id==='summitSearch'?'input':'change',renderSummitLedger)
 });
 document.getElementById('resetSummitFilters')?.addEventListener('click',()=>{
  const search=document.getElementById('summitSearch');if(search)search.value='';
  const range=document.getElementById('summitRangeFilter');if(range)range.value='all';
  renderSummitLedger();
  announceSummitGroups('Summit filters reset.')
 });
 document.getElementById('showPlannedSummits')?.addEventListener('click',()=>{
  /* v8.3 — this used to drive the retired Status dropdown. It now opens the
     Planned group and collapses the other two, which is the same intent. */
  const search=document.getElementById('summitSearch');if(search)search.value='';
  const range=document.getElementById('summitRangeFilter');if(range)range.value='all';
  SUMMIT_GROUP_ORDER.forEach(g=>{summitGroupsOpen[g.id]=g.id==='planned'});
  saveSummitGroups();
  renderSummitLedger();
  announceSummitGroups('Planned expanded; completed and remaining collapsed.');
  document.getElementById('summitGrid')?.scrollIntoView({behavior:'smooth',block:'start'})
 });
 document.getElementById('rangeSummary')?.addEventListener('click',event=>{
  const button=event.target.closest('[data-range-card]');if(!button)return;
  const rf=document.getElementById('summitRangeFilter');if(rf)rf.value=button.dataset.rangeCard;
  /* A range card should reveal its peaks, not drop them into collapsed groups. */
  SUMMIT_GROUP_ORDER.forEach(g=>{summitGroupsOpen[g.id]=true});
  saveSummitGroups();
  renderSummitLedger();
  document.getElementById('summitGrid')?.scrollIntoView({behavior:'smooth',block:'start'})
 });
 document.getElementById('expandAllSummits')?.addEventListener('click',()=>setAllSummitGroups(true));
 document.getElementById('collapseAllSummits')?.addEventListener('click',()=>setAllSummitGroups(false));
 document.getElementById('summitGrid')?.addEventListener('click',event=>{
  const toggle=event.target.closest('[data-group-toggle]');
  if(toggle){toggleSummitGroup(toggle.dataset.groupToggle);return}
  const card=event.target.closest('[data-summit-name]');if(card)openSummitDetail(card.dataset.summitName)
 });
 document.getElementById('summitDetailClose')?.addEventListener('click',closeSummitDetail);
 document.getElementById('summitDetailOverlay')?.addEventListener('click',event=>{if(event.target.id==='summitDetailOverlay')closeSummitDetail()});
 document.addEventListener('keydown',event=>{
  if(event.key==='Escape'&&!document.getElementById('summitDetailOverlay')?.hidden)closeSummitDetail()
 });
 renderRangeSummary();renderSummitLedger()
}


function flashReadinessTarget(el){
 if(!el)return;
 el.classList.add('readiness-target-flash');
 setTimeout(()=>el.classList.remove('readiness-target-flash'),1400);
}
function openReadinessChecks(){
 const panel=document.getElementById('readiness-checks');
 if(!panel)return;
 panel.scrollIntoView({behavior:'smooth',block:'start'});
 flashReadinessTarget(panel);
 setTimeout(()=>panel.focus({preventScroll:true}),350);
}
function openGearChecklistFromReadiness(){
 const details=document.getElementById('smartPackBuilderPanel');
 if(details)details.open=true;
 const target=document.getElementById('packSections')||details;
 target?.scrollIntoView({behavior:'smooth',block:'start'});
 flashReadinessTarget(details||target);
}
function openCommunicationChecksFromReadiness(){
 const target=document.getElementById('communicationChecksCard');
 target?.scrollIntoView({behavior:'smooth',block:'center'});
 flashReadinessTarget(target);
 setTimeout(()=>target?.focus({preventScroll:true}),350);
}
function setupReadinessNavigation(){
 const metric=document.getElementById('readinessMetric');
 if(metric){
  metric.addEventListener('click',openReadinessChecks);
  metric.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openReadinessChecks()}});
 }
 document.getElementById('openGearChecklist')?.addEventListener('click',openGearChecklistFromReadiness);
 document.getElementById('openCommunicationChecks')?.addEventListener('click',openCommunicationChecksFromReadiness);
}


/* Version 7.6 — tappable dashboard cards */
function flashDashboardDestination(el){
 if(!el)return;
 el.classList.add('dashboard-destination-flash');
 setTimeout(()=>el.classList.remove('dashboard-destination-flash'),1400);
}
function openDashboardShortcut(card){
 const action=card.dataset.dashboardAction;
 if(action==='focus'){
  if(typeof openFocus==='function')openFocus();
  else document.getElementById('focus')?.scrollIntoView({behavior:'smooth',block:'start'});
  return;
 }
 const targetId=card.dataset.dashboardTarget;
 const target=targetId?document.getElementById(targetId):null;
 if(!target)return;
 if(target.tagName==='DETAILS')target.open=true;
 target.scrollIntoView({behavior:'smooth',block:'start'});
 flashDashboardDestination(target);
 try{target.focus({preventScroll:true})}catch(e){}
}
function setupDashboardShortcuts(){
 document.querySelectorAll('.dashboard-shortcut[data-dashboard-target],.dashboard-shortcut[data-dashboard-action]').forEach(card=>{
  card.addEventListener('click',event=>{
   if(event.target.closest('a,button,input,label,select,textarea,summary'))return;
   openDashboardShortcut(card);
  });
  card.addEventListener('keydown',event=>{
   if(event.key==='Enter'||event.key===' '){
    event.preventDefault();
    openDashboardShortcut(card);
   }
  });
 });
}

