function futurePointById(id){return FUTURE_WEATHER_POINTS.find(x=>x.id===id)||null}

function populateFutureWeatherOptions(){
 const select=document.getElementById('heroWeatherLocation');
 if(!select||select.dataset.futureBuilt)return;
 const byGroup=new Map();
 FUTURE_WEATHER_POINTS.forEach(p=>{if(!byGroup.has(p.group))byGroup.set(p.group,[]);byGroup.get(p.group).push(p)});
 byGroup.forEach((points,group)=>{
  const og=document.createElement('optgroup');
  og.label=`Future · ${group}`;
  points.forEach(p=>{
   const o=document.createElement('option');
   o.value=p.id;
   o.textContent=`${p.name} · ${p.elevationFt.toLocaleString()} ft`;
   og.appendChild(o);
  });
  select.appendChild(og);
 });
 select.dataset.futureBuilt='1';
}



